export const PYQ_STATS = STATS
export const PYQ_SUBJECTS = PYQ_YEARS.flatMap((y) => y.subjects.map((s) => ({ ...s, year: y.year, available: !!STATS[s.id] })))
export const pyqSubject = (id) => PYQ_SUBJECTS.find((s) => s.id === id) || null

// Each subject's questions are a separate chunk, loaded on first open.
const loaders = import.meta.glob(['./pyq/*.json', '!./pyq/index.json'])
export async function loadPyq(id) {
  const fn = loaders[`./pyq/${id}.json`]
  return fn ? (await fn()).default : []
}
